const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/accident_logs',
  qs: {
    per_page: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    log_date: 'SOME_STRING_VALUE',
    start_date: 'SOME_STRING_VALUE',
    end_date: 'SOME_STRING_VALUE',
    'filters[created_by_id]': 'SOME_INTEGER_VALUE',
    'filters[location_id]': 'SOME_ARRAY_VALUE',
    'filters[daily_log_segment_id]': '123456'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/accident_logs?per_page=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&log_date=SOME_STRING_VALUE&start_date=SOME_STRING_VALUE&end_date=SOME_STRING_VALUE&filters%5Bcreated_by_id%5D=SOME_INTEGER_VALUE&filters%5Blocation_id%5D=SOME_ARRAY_VALUE&filters%5Bdaily_log_segment_id%5D=123456"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

